  if (!body.diff || body.diff.length === 0) throw new BadRequestException();
  const vector = await this.voyage.embed(body.diff);
  const hits = await this.chroma.query(vector);
  return hits.filter((h) => h.score > 0.5);
}

examples.good:
@Post('search')
async search(@Body() dto: SearchRequestDto) {
  const hits = await this.embeddings.search(dto.diff, { k: dto.k });
  return { hits };
}

